	private static function remote_url($url){$url=esc_url_raw((string)$url,array('https'));if(!$url)return '';$p=wp_parse_url($url);$host=strtolower((string)($p['host']??''));$scheme=strtolower((string)($p['scheme']??''));$port=isset($p['port'])?(int)$p['port']:443;if('https'!==$scheme||!$host||443!==$port||isset($p['user'])||isset($p['pass']))return '';if(in_array($host,array('localhost','localhost.localdomain','metadata.google.internal'),true)||str_ends_with($host,'.local')||str_ends_with($host,'.internal'))return '';if(filter_var($host,FILTER_VALIDATE_IP)){if(false===filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))return '';}return $url;}
