	private function compensate_ingest($event,$ingest,$code){$context=array('provider'=>$this->provider_id,'live_public_id'=>VWLB_Helpers::text($event['public_id']??'',80),'provider_ref'=>VWLB_Helpers::text($ingest['provider_ref']??'',191),'reason'=>sanitize_key($code));try{$result=apply_filters('vwlb_provider_revoke_ingest_result',null,$context);}catch(Throwable $e){$result=null;} $confirmed=true===$result||(is_array($result)&&in_array(sanitize_key((string)($result['status']??'')),array('revoked','deleted','disabled','rotated','not_found'),true));if(!$confirmed)return $this->error('vwlb_provider_ingest_reconcile_required',__('Provider ingest output was unsafe and provider revocation could not be confirmed. Reconciliation is required.',VWLB_TEXT_DOMAIN),array('reconcile_required'=>true,'live_public_id'=>$context['live_public_id']));return $this->error($code,__('Provider ingest output failed File 10 security validation and was compensated.',VWLB_TEXT_DOMAIN));}
