	public function issue_ingest($event){$value=$this->inner->issue_ingest($event);if(is_wp_error($value))return $value;if(!is_array($value))return $this->error('vwlb_provider_ingest_reconcile_required',__('The provider returned an invalid ingest result. Its external outcome is uncertain and requires reconciliation.',VWLB_TEXT_DOMAIN),array('reconcile_required'=>true,'live_public_id'=>VWLB_Helpers::text($event['public_id']??'',80)));$url=self::remote_url($value['ingest_url']??'');if(!$url)return $this->compensate_ingest($event,$value,'vwlb_provider_ingest_url_invalid');$value['ingest_url']=$url;if(array_key_exists('stream_key',$value)){if(!is_scalar($value['stream_key']))return $this->compensate_ingest($event,$value,'vwlb_provider_stream_secret_invalid');$secret=(string)$value['stream_key'];if(strlen($secret)<16||strlen($secret)>512||preg_match('/[\x00-\x1F\x7F]/',$secret))return $this->compensate_ingest($event,$value,'vwlb_provider_stream_secret_invalid');$value['stream_key']=$secret;}if(isset($value['provider_ref']))$value['provider_ref']=VWLB_Helpers::text($value['provider_ref'],191);return $value;}
	public function playback($object,$viewer){$value=$this->inner->playback($object,$viewer);if(is_wp_error($value))return $value;if(!is_array($value)||empty($value['url']))return $this->error('vwlb_provider_playback_contract_invalid',__('Media provider returned an invalid playback contract.',VWLB_TEXT_DOMAIN));$url=self::remote_url($value['url']);if(!$url)return $this->error('vwlb_provider_playback_url_invalid',__('Media provider returned an unsafe playback URL.',VWLB_TEXT_DOMAIN));if('youtube'===$this->provider_id&&'www.youtube-nocookie.com'!==strtolower((string)wp_parse_url($url,PHP_URL_HOST)))return $this->error('vwlb_provider_playback_url_invalid',__('YouTube playback must remain on the approved privacy-enhanced host.',VWLB_TEXT_DOMAIN));if('vimeo'===$this->provider_id&&'player.vimeo.com'!==strtolower((string)wp_parse_url($url,PHP_URL_HOST)))return $this->error('vwlb_provider_playback_url_invalid',__('Vimeo playback must remain on the approved player host.',VWLB_TEXT_DOMAIN));$value['url']=$url;return $value;}
	public function process_asset($asset,$job){$value=$this->inner->process_asset($asset,$job);if(is_wp_error($value))return $value;if(!is_array($value))return $this->error('vwlb_provider_processing_contract_invalid',__('Media processor returned an invalid result contract.',VWLB_TEXT_DOMAIN));if(isset($value['derivatives'])&&!is_array($value['derivatives']))return $this->error('vwlb_provider_processing_contract_invalid',__('Media processor returned invalid derivative metadata.',VWLB_TEXT_DOMAIN));foreach((array)($value['derivatives']??array()) as $key=>$url){if(!in_array(sanitize_key((string)$key),array('hls','hls_low','mp4','mp4_high','mp4_low','audio_only','mp3','poster','storyboard'),true))continue;if(!is_scalar($url)||!self::remote_url((string)$url))return $this->error('vwlb_provider_derivative_url_invalid',__('Media processor returned an unsafe derivative URL.',VWLB_TEXT_DOMAIN),array('derivative'=>sanitize_key((string)$key)));$value['derivatives'][$key]=self::remote_url((string)$url);}return $value;}
	public function verify_webhook($headers,$body){return (bool)$this->inner->verify_webhook($headers,$body);}
	public function reconcile($object_type,$object){$value=$this->inner->reconcile($object_type,$object);if(is_wp_error($value))return $value;return is_array($value)?$value:$this->error('vwlb_provider_reconcile_contract_invalid',__('Media provider returned an invalid reconciliation result.',VWLB_TEXT_DOMAIN));}
