final class VWLB_R113_Provider_Output_Guard {
	public static function register(){foreach(VWLB_Providers::all() as $provider){if($provider instanceof VWLB_R113_Validated_Provider)continue;VWLB_Providers::register(new VWLB_R113_Validated_Provider($provider));}}
}
